import { Abilities } from "./enums/abilities";
import { Pokemon } from "./enums/pokemon";
import { abilityEffects } from "./texts/abilityTexts";

export class Ability {
    constructor(
        public readonly id: Abilities,              // Unique ID from PokeAPI
        public readonly name: string,            // Name of the ability
        public readonly isMainSeries: boolean,   // Whether it's a main-series ability
        public readonly generation: number,      // Generation where it was introduced
        public readonly pokemon: Pokemon[],       // List of Pokémon names that have this ability
    ) {}

    /** Get the effect of this ability */
    getEffect() {
        return abilityEffects[this.id].effect;
    }

    /** Get the short effect of this ability */
    getShortEffect() {
        return abilityEffects[this.id].shortEffect;
    }

    /** Get the flavor text of this ability */
    getFlavorText() {
        return abilityEffects[this.id].flavorText;
    }
}

